export const TRAINERS = [{"name":"Master Halric Vane","teaches":"Swordsmanship Lv.22","where":"Golden Lion training yard","place":"aurelia-city","detail":"Golden Lion training yard. 150 sp/session. Requires F-Rank registration. Blunt, patient, genuinely good. Will not take a student who has not been hit yet, and arranges that first."},{"name":"Ser Maud Everly","teaches":"Shield Use Lv.21, Leadership Lv.17","where":"City Watch drillmaster, Eastgate barracks","place":"aurelia-city","detail":"City Watch drillmaster, Eastgate barracks. 90 sp. Trains in groups of six; being the worst in the group is the point."},{"name":"Brannoc Tull","teaches":"Archery Lv.18, Survival Lv.16","where":"the butts outside Eastgate","place":"aurelia-city","detail":"the butts outside Eastgate. 40 sp, cheapest real instruction in the city. Retired Iron Vanguard, missing three fingers on the left hand, still outshoots everyone."},{"name":"Magister Ilya Ferrant","teaches":"Arcana Lv.24, Evocation","where":"Silver Moon chapterhouse (the Society's true seat is Luminor, three days north)","place":"aurelia-city","detail":"Silver Moon chapterhouse (the Society's true seat is Luminor, three days north). 400 sp/month tuition, requires Intellect 13+ and a passed entrance interrogation. Contemptuous of the self-taught."},{"name":"Sister Aveline Corr","teaches":"First Aid Lv.24, Medicine Lv.19","where":"Temple of the Dawn infirmary","place":"aurelia-city","detail":"Temple of the Dawn infirmary. Free, in exchange for three days' work on the ward per lesson. The work is not pleasant and she is watching to see if you flinch."},{"name":"Dagna Ironhand","teaches":"Blacksmithing Lv.26","where":"Anvil Row","place":"aurelia-city","detail":"Anvil Row. Will not teach lessons at all: six-month apprenticeship or nothing, 500 sp bond up front, returned if you finish."},{"name":"Corvin \"Grey\" Aszelay","teaches":"Stealth Lv.20, Sleight of Hand Lv.23","where":"Ratsend, findable only if he wants to be","place":"aurelia-city","detail":"Ratsend, findable only if he wants to be. Runs the Ravens' forward cell here, not the order itself, which is seated at Grayhaven. Requires Shadow Ravens standing +1 or an introduction. Payment in favors, never coin."},{"name":"Old Pell","teaches":"Fishing Lv.15, Foraging Lv.17","where":"the river stairs below the Guild bridge","place":"aurelia-city","detail":"the river stairs below the Guild bridge. Free. Talks continuously. Knows every rumor on the water and most of them are true."},{"name":"Brother Anselm","teaches":"Herbalism Lv.19, Religion Lv.22","where":"Kingsrest Monastery (-55,+120)","place":"kingsrest-monastery","detail":"Kingsrest Monastery (-55,+120). Free to anyone who works the garden. Silent order: instruction is by demonstration only."},{"name":"Hesper Dunn","teaches":"Animal Handling Lv.20, Riding Lv.18","where":"Millrun (+60,+70)","place":"millrun","detail":"Millrun (+60,+70). 60 sp. Breeds the best horses in the heartland and will refuse to sell you one if she dislikes how you sit."},{"name":"Tomas Reyne","teaches":"Lockpicking Lv.17, Trap Handling Lv.19","where":"Silverstream (+90,-80), officially a locksmith","place":"silverstream","detail":"Silverstream (+90,-80), officially a locksmith. 200 sp and pointed questions about why you want to know."},{"name":"Karak Stonebrow","teaches":"Axe Fighting Lv.28, Blacksmithing Lv.22","where":"Karak Borgor (+360,+360)","place":"karak-borgor","detail":"Karak Borgor (+360,+360). Will teach outsiders, for a price and an oath. The oath is real and binding."},{"name":"Faelith of the Weeping Grove","teaches":"Nature Lv.30, Herbalism Lv.28","where":"the Weeping Grove (-480,+200)","place":"the-weeping-grove","detail":"the Weeping Grove (-480,+200). Refuses outsiders absolutely unless they arrive carrying a boon granted by the Circle of Nine, which is itself a quest."},{"name":"Tarrin Vosk","teaches":"Dual Wielding Lv.25, Acrobatics Lv.22","where":"Wyrmstooth (+180,+640)","place":"wyrmstooth","detail":"Wyrmstooth (+180,+640). Teaches anyone who beats one of his current students. Losing is free; winning costs 300 sp."},{"name":"Zayd al-Marran","teaches":"Deception Lv.27, Insight Lv.24, Persuasion Lv.25","where":"Saffaron (-820,-320)","place":"saffaron","detail":"Saffaron (-820,-320). Nominally a rug merchant. Tuition is information, never money."},{"name":"Captain Nerissa Quill","teaches":"Navigation Lv.26, Swimming Lv.22, Leadership Lv.20","where":"Port Meridian (-80,-480)","place":"port-meridian","detail":"Port Meridian (-80,-480). Sea Drake captain. Teaches only crew, so the price is a voyage."},{"name":"The Ashen Widow","teaches":"Necromancy Lv.29, Umbral Lv.26","where":"Necrospire (+630,-120)","place":"necrospire","detail":"Necrospire (+630,-120). Teaches willingly. The price is always something the student did not realize they valued. The Guild's position is that studying with her is not itself a crime, and the Church of the Dawn's positio"},{"name":"Master Ovid Lorne","teaches":"Spear Fighting Lv.33","where":"a hermit in the ruined tower at Rookspire (+65,+160)","place":"rookspire","detail":"a hermit in the ruined tower at Rookspire (+65,+160). The highest weapon mastery known to be alive. Accepts no students, has accepted three in sixty years, and the test is not announced. Reaching him is easy; being taugh"}];
