export const AURELIA_PEOPLE = [{"name":"Clerk Maren Holt","desc":"Guild registry desk, twenty-two years behind it. Knows every adventurer in the city by face and most by their debts. Dry, kind under it, genuinely wants the new ones to survive. She is the first NPC most players meet."},{"name":"Quest Administrator Doran Vale","desc":"assigns and verifies requests. Rigid about paperwork, fair about payment, and will quietly warn a party off a job he thinks will kill them."},{"name":"Examiner Sylas Reigh","desc":"runs promotion trials for F through C. Failed more candidates than he passed. Not cruel, just unwilling to certify someone who will die on their first D-Rank job."},{"name":"Lord Mayor Cassian Verrow","desc":"ambitious, cultivating the king's second daughter, in debt to the Sea Drake Company for reasons he would prefer stayed quiet."},{"name":"Captain-Commander Bryse Odal","desc":"Watch commander, ex-Iron Vanguard, dislikes adventurers on principle and uses them constantly."},{"name":"High Sister Elowen","desc":"Temple of the Dawn. Politically shrewd, theologically flexible, absolutely immovable on necromancy."},{"name":"Fingers Nel","desc":"Ratsend fence, twelve years old, works for someone nobody has met. Fair prices, no questions, will not handle anything from a temple."}];
